 const pending=clientIdeas.length+inReview.length,pendingText=[clientIdeas.length?pl(clientIdeas.length,'idea por decidir','ideas por decidir'):'',inReview.length?pl(inReview.length,'pieza en revisión','piezas en revisión'):''].filter(Boolean).join(' y ');
 const timePct=pct(elapsed,total),spendPct=pct(camp.spent,camp.budget);
 const pace=phase!=='during'||!camp.budget?'':Math.abs(spendPct-timePct)<=10?'Al ritmo previsto':spendPct>timePct?'Por encima del ritmo previsto':'Por debajo del ritmo previsto';
 // Línea de tiempo común a todas las filas de momentos.
