 if(start)for(let d=new Date(a);d.getTime()<b;d=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,1)))months.push({t:Math.max(a,d.getTime()),label:d.toLocaleDateString('es-ES',{month:'short',timeZone:'UTC'})});
 const todayLeft=phase==='during'?pct(ts(today)+dayMs/2-a,span):-1;
