 moments.forEach(m=>{if(m.start>today&&m.start<=week){const n=posts.filter(p=>p.moment_id===m.id).length;agenda.push({key:'m-'+m.id,day:m.start,title:`Empieza «${m.name}»`,sub:[pl(n,'pieza','piezas'),numbers&&m.budget?money(m.budget)+' de ads':''].filter(Boolean).join(' · '),chip:<span className="lb-chip state-draft">Momento</span>});}});
 agenda.sort((x,y)=>x.day.localeCompare(y.day));
