   <div className="lb-stats"><span><b>{posts.length}</b>piezas</span><span><b>{posts.filter(p=>p.status==='Idea aprobada').length}</b>ideas aprobadas</span><span><b>{posts.filter(p=>p.status==='Borrador').length}</b>borradores</span></div>
